mkdir -p /tmp/knock-bot-check && cat > /tmp/knock-bot-check/check.mjs <<'EOF'
import { checkSms } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/knock-inv-g1-1/bot.mjs';

let failures = 0;
const fail = (msg) => { failures++; console.log('FAIL', msg); };
const localHour = (d, tz) => new Intl.DateTimeFormat('en-US', { timeZone: tz, hourCycle: 'h23', hour: 'numeric', minute: 'numeric', second: 'numeric' }).format(d);
const iso = (d) => (d ? d.toISOString() : null);

// Named cases
const cases = [
  ['2026-10-23T15:00:00Z', 'America/Chicago', true],   // 10:00 CDT
  ['2026-10-23T03:00:00Z', 'America/Chicago', false],  // 22:00 CDT Oct 22 -> next 08:00 CDT Oct 23 = 13:00Z
  ['2026-10-23T12:30:00Z', 'America/Chicago', false],  // 07:30 CDT -> 08:00 CDT Oct 23 = 13:00Z
  ['2026-10-23T13:00:00Z', 'America/Chicago', true],   // exactly 08:00 CDT
  ['2026-10-24T01:59:59Z', 'America/Chicago', true],   // 20:59:59 CDT
  ['2026-10-24T02:00:00Z', 'America/Chicago', false],  // 21:00 CDT -> 08:00 CDT Oct 25 = 13:00Z Oct 25
  ['2026-10-23T20:00:00Z', 'Asia/Kolkata', false],     // 01:30 IST Oct 24 -> 08:00 IST = 02:30Z Oct 24
  ['2026-10-24T02:30:00Z', 'Asia/Kolkata', true],      // 08:00 IST
  ['2026-10-23T12:00:00Z', 'Asia/Kathmandu', false],   // 17:45 NPT -> next 08:00 NPT Oct 24 = 02:15Z Oct 24
  ['2026-10-23T12:00:00Z', 'Australia/Lord_Howe', true], // 22:30 +11 -> held actually; check below
  ['2026-10-31T23:00:00Z', 'America/New_York', true],  // 19:00 EDT
  ['2026-11-01T02:00:00Z', 'America/New_York', false], // 22:00 EDT Oct 31 -> 08:00 EST Nov 1 = 13:00Z Nov 1
  ['2026-10-23T15:00:00Z', null, false],
  ['2026-10-23T15:00:00Z', 'Mars/Olympus', false],
  ['2026-10-23T15:00:00Z', '', false],
];
for (const [t, tz, expectAllowed] of cases) {
  const now = new Date(t);
  const r = checkSms({ id: 'u', phone: '+13125550142', timezone: tz }, now);
  console.log(String(tz).padEnd(20), t, '->', r.allowed, iso(r.nextAllowedAt), '|', r.reason);
  if (r.allowed !== expectAllowed) fail(`${t} ${tz} expected allowed=${expectAllowed}`);
  if (!r.allowed && tz && isValid(tz)) {
    if (!r.nextAllowedAt || r.nextAllowedAt <= now) fail(`${t} ${tz} nextAllowedAt not in future`);
  }
  if (!r.allowed && !isValid(tz) && r.nextAllowedAt !== null) fail(`${t} invalid tz should have null nextAllowedAt`);
}
function isValid(tz) { try { new Intl.DateTimeFormat('en-US', { timeZone: tz }); return true; } catch { return false; } }

// Lord Howe: 2026-10-23T12:00Z is 23:00 +11 -> should be held
const lh = checkSms({ timezone: 'Australia/Lord_Howe' }, new Date('2026-10-23T12:00:00Z'));
console.log('Lord_Howe 12:00Z ->', lh.allowed, iso(lh.nextAllowedAt), lh.reason);
if (lh.allowed) fail('Lord_Howe should be held at 23:00 local');

// Invalid now
const bad = checkSms({ timezone: 'America/Chicago' }, new Date('nope'));
console.log('invalid now ->', bad.allowed, bad.nextAllowedAt, bad.reason);
if (bad.allowed || bad.nextAllowedAt !== null) fail('invalid now');

// Exhaustive sweep: zones x instants every 17 minutes over ~14 months, covering DST changes.
const zones = ['America/Chicago', 'America/New_York', 'America/Los_Angeles', 'America/Anchorage', 'Pacific/Honolulu',
  'America/Phoenix', 'Asia/Kolkata', 'Asia/Kathmandu', 'Australia/Lord_Howe', 'America/Santiago', 'Asia/Tehran',
  'Europe/London', 'Pacific/Chatham', 'UTC'];
const start = Date.UTC(2026, 0, 1);
const end = Date.UTC(2027, 2, 1);
let checked = 0, held = 0;
for (const tz of zones) {
  for (let t = start; t < end; t += 17 * 60000) {
    const now = new Date(t);
    const r = checkSms({ timezone: tz }, now);
    checked++;
    const h = Number(localHour(now, tz).split(':')[0]);
    const inWindow = h >= 8 && h < 21;
    if (r.allowed !== inWindow) { fail(`window mismatch ${tz} ${now.toISOString()} local hour ${h}`); break; }
    if (r.allowed) continue;
    held++;
    const n = r.nextAllowedAt;
    if (!(n > now)) { fail(`not in future ${tz} ${now.toISOString()}`); break; }
    if (localHour(n, tz) !== '08:00:00') { fail(`nextAllowedAt not 08:00 local ${tz} ${now.toISOString()} -> ${n.toISOString()} = ${localHour(n, tz)}`); break; }
    const justBefore = checkSms({ timezone: tz }, new Date(n.getTime() - 1));
    if (justBefore.allowed) { fail(`allowed 1ms before nextAllowedAt ${tz} ${n.toISOString()}`); break; }
    const atNext = checkSms({ timezone: tz }, n);
    if (!atNext.allowed) { fail(`not allowed at nextAllowedAt ${tz} ${n.toISOString()}`); break; }
  }
}
console.log(`sweep: ${checked} checks, ${held} held, failures so far: ${failures}`);
console.log(failures === 0 ? 'ALL CHECKS PASSED' : `${failures} FAILURE(S)`);
process.exitCode = failures ? 1 : 0;
EOF
cd /tmp/knock-bot-check && TZ=Asia/Tokyo node check.mjs; echo "exit=$?"
